class Solution {
public:
    int findNumberOfLIS(vector<int>& nums) {
        int n = nums.size();
        vector<int> lengths(n, 1), counts(n, 1);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (nums[i] > nums[j]) {
                    if (lengths[j] + 1 > lengths[i]) {
                        lengths[i] = lengths[j] + 1;
                        counts[i] = counts[j];
                    } else if (lengths[j] + 1 == lengths[i]) {
                        counts[i] += counts[j];
                    }
                }
            }
        }
        int maxLen = *max_element(lengths.begin(), lengths.end());
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            if (lengths[i] == maxLen) ans += counts[i];
        }
        return ans;
    }
};

class Solution {
    public int findNumberOfLIS(int[] nums) {
        int n = nums.length;
        int[] lengths = new int[n];
        int[] counts = new int[n];
        Arrays.fill(lengths, 1);
        Arrays.fill(counts, 1);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[i] > nums[j]) {
                    if (lengths[j] + 1 > lengths[i]) {
                        lengths[i] = lengths[j] + 1;
                        counts[i] = counts[j];
                    } else if (lengths[j] + 1 == lengths[i]) {
                        counts[i] += counts[j];
                    }
                }
            }
        }
        int maxLen = 0;
        for (int l : lengths) if (l > maxLen) maxLen = l;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            if (lengths[i] == maxLen) ans += counts[i];
        }
        return ans;
    }
}

var findNumberOfLIS = function(nums) {
    const n = nums.length;
    const lengths = new Array(n).fill(1);
    const counts = new Array(n).fill(1);
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (nums[i] > nums[j]) {
                if (lengths[j] + 1 > lengths[i]) {
                    lengths[i] = lengths[j] + 1;
                    counts[i] = counts[j];
                } else if (lengths[j] + 1 === lengths[i]) {
                    counts[i] += counts[j];
                }
            }
        }
    }
    const maxLen = Math.max(...lengths);
    let ans = 0;
    for (let i = 0; i < n; i++) {
        if (lengths[i] === maxLen) ans += counts[i];
    }
    return ans;
};
